def create_database_client(host="localhost", port=5432, **custom_options):
    default_config = {
        "host": host,
        "port": port,
        "ssl": True,
        "timeout": 30
    }
    # Override defaults with caller's custom kwargs
    final_config = {**default_config, **custom_options}
    return final_config

